// ---- Switches (pipeline callers can override via `settings`) ----
const DEFAULTS = {
  tier_alumni: true,             // Tier 1: same school
  tier1_keyword_filter: true,    // Tier 1 first searches alumni with the peer titles; plain alumni search becomes a fallback
  tier_ex_colleagues: true,      // Tier 2: same past employer
  tier_same_team: true,          // Tier 3: peer titles in the job's city
  enrich_profiles: true,         // full profiles for the shortlist (pass-2 scoring)
  find_emails: true,             // email search + fallback email finder
  draft_messages: true,          // Claude drafts
  save_as_gmail_drafts: false,   // no Gmail credential yet
  min_contacts_before_next_tier: 3,
  shortlist_size: 5,             // pass-1 shortlist that gets enriched
  contacts_per_job: 3,           // drafts per job (pass 2), recruiter extra
  search_pages_per_query: 1,     // 1 page = up to 25 profiles ($0.10)
  model_light: 'claude-haiku-4-5-20251001',   // Step 3 job keywords
  model_drafts: 'claude-sonnet-5'    // Step 8 message drafts
};

return $input.all().map(i => ({
  json: { ...i.json, settings: { ...DEFAULTS, ...(i.json.settings || {}) } }
}));

// Normalize company URLs, schools, past employers, city; group jobs by company.
const items = $('Settings').all().map(i => i.json);

const SCHOOL_ALIASES = {
  'tu/e': 'Eindhoven University of Technology',
  'tue': 'Eindhoven University of Technology',
  'technische universiteit eindhoven': 'Eindhoven University of Technology',
  'tu delft': 'Delft University of Technology',
  'uva': 'University of Amsterdam'
};
const normCompany = u => {
  const m = String(u || '').match(/linkedin\.com\/company\/([^/?#]+)/i);
  return m ? `https://www.linkedin.com/company/${decodeURIComponent(m[1]).toLowerCase()}` : '';
};
const normProfile = u => {
  const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i);
  return m ? `https://www.linkedin.com/in/${decodeURIComponent(m[1])}` : ''; // keep case: ACwAA... ids are case-sensitive
};

const contacted = $input.all()
  .map(i => normProfile(i.json && i.json.linkedin_url))
  .filter(Boolean);

const groups = {};
for (const it of items) {
  const job = it.job || {};
  const cand = it.candidate || {};
  const companyUrl = normCompany(job.companyUrl);
  const key = companyUrl || ('name:' + String(job.companyName || '').toLowerCase());
  if (!groups[key]) {
    const edu = cand.education || [];
    const schools = [...new Set(edu.map(e => {
      const s = typeof e === 'string' ? e : (e && e.school);
      return SCHOOL_ALIASES[String(s || '').toLowerCase().trim()] || s;
    }).filter(Boolean))];
    const school_terms = [...new Set(edu.flatMap(e => typeof e === 'string' ? [e] : [e.school, ...(e.school_aliases || [])])
      .concat(schools).filter(Boolean).map(s => String(s).toLowerCase()))];
    const past_companies = (cand.experience || [])
      .map(e => (typeof e === 'string' ? { company: e } : e))
      .map(e => ({ name: e.company || '', url: normCompany(e.company_linkedin_url) }))
      .filter(e => (e.url || e.name) && e.url !== companyUrl);
    groups[key] = {
      company: { name: job.companyName || '', url: companyUrl },
      city: String(job.location || '').split(',')[0].trim(),
      jobs: [],
      candidate: cand,
      settings: it.settings,
      schools,
      school_terms,
      past_companies,
      past_company_urls: [...new Set(past_companies.map(p => p.url).filter(Boolean))],
      contacted
    };
  }
  groups[key].jobs.push(job);
}
return Object.values(groups).map(g => ({ json: g }));

const ctx = $('Loop companies').first().json;
const res = $input.first().json || {};
let text = '';
if (Array.isArray(res.content)) text = res.content.filter(c => c.type === 'text').map(c => c.text).join('\n');
else text = res.text || res.merged_response || '';

let kw = {};
try { const m = text.match(/\{[\s\S]*\}/); kw = JSON.parse(m ? m[0] : text); } catch (e) { kw = {}; }

const team_keywords = (kw.team_keywords || []).filter(Boolean).map(String).slice(0, 5);
let peer_titles = (kw.peer_titles || []).filter(Boolean).map(String).slice(0, 3);
if (!peer_titles.length) peer_titles = [...new Set(ctx.jobs.map(j => j.title).filter(Boolean))].slice(0, 3);

return [{ json: {
  ...ctx,
  team_keywords,
  peer_titles,
  keywords_error: team_keywords.length ? null : (res.error ? JSON.stringify(res.error).slice(0, 300) : text.slice(0, 300))
} }];

const ctx = $input.first().json;
const s = ctx.settings;
const EXCLUDE = ['Recruiter', 'Talent Acquisition', 'Recruitment', 'HR', 'Human Resources'];
const run = !!(s.tier_alumni && ctx.company.url && ctx.schools.length);
// LinkedIn boolean query: alumni who hold one of the peer titles (keeps big companies relevant)
const query = s.tier1_keyword_filter && (ctx.peer_titles || []).length
  ? ctx.peer_titles.slice(0, 3).map(t => `"${t}"`).join(' OR ') : '';
return [{ json: {
  ...ctx,
  run_tier1: run,
  tier1_body: run ? {
    profileScraperMode: 'Short',
    currentCompanies: [ctx.company.url],
    schools: ctx.schools,
    excludeCurrentJobTitles: EXCLUDE,
    takePages: s.search_pages_per_query,
    maxItems: 25 * s.search_pages_per_query,
    ...(query ? { searchQuery: query } : {})
  } : null
} }];

const ctx = $('Plan tier 1').first().json;
const rows = ctx.run_tier1 ? $input.all().map(i => i.json) : [];
const errors = rows.filter(r => r && r.error).map(r => r.error.message || JSON.stringify(r.error).slice(0, 200));
const people = rows
  .filter(r => r && !r.error && (r.linkedinUrl || r.publicIdentifier))
  .map(r => ({ ...r, _tiers: ['alumni'] }));

const { tier1_body, run_tier1, ...rest } = ctx;
return [{ json: { ...rest, found: people, search_errors: errors, searches_run: run_tier1 ? 1 : 0,
  tier1_query: (run_tier1 && tier1_body && tier1_body.searchQuery) || '' } }];

// Tier 1b (alumni without title filter), Tier 2 (ex-colleagues) and Tier 3 (same team), only when switched on and possible.
const ctx = $input.first().json;
const s = ctx.settings;
const EXCLUDE = ['Recruiter', 'Talent Acquisition', 'Recruitment', 'HR', 'Human Resources'];
const base = {
  profileScraperMode: 'Short',
  currentCompanies: [ctx.company.url],
  excludeCurrentJobTitles: EXCLUDE,
  takePages: s.search_pages_per_query,
  maxItems: 25 * s.search_pages_per_query
};
const reqs = [];
// Tier 1b: alumni without the title filter (only if Tier 1 used one)
if (ctx.company.url && s.tier_alumni && ctx.tier1_query && ctx.schools.length) {
  reqs.push({ tier: 'alumni', body: { ...base, schools: ctx.schools } });
}
if (ctx.company.url && s.tier_ex_colleagues && ctx.past_company_urls.length) {
  reqs.push({ tier: 'ex_colleague', body: { ...base, pastCompanies: ctx.past_company_urls } });
}
if (ctx.company.url && s.tier_same_team && ctx.peer_titles.length) {
  // no location filter: job cities are often small towns (e.g. Duizel); same city only adds +1 in scoring
  reqs.push({ tier: 'same_team', body: { ...base, currentJobTitles: ctx.peer_titles } });
}
if (!reqs.length) return [{ json: { ...ctx, run_fallback: false } }];
return reqs.map(r => ({ json: { run_fallback: true, tier: r.tier, body: r.body } }));

const ctx = $('Collect tier 1').first().json;
const reqs = $('Plan fallback searches').all().map(i => i.json);
const people = [...ctx.found];
const errors = [...(ctx.search_errors || [])];

$input.all().forEach((item, idx) => {
  const r = item.json;
  if (!r || !Object.keys(r).length) return;
  let tier = reqs.length === 1 ? reqs[0].tier : 'same_team';
  try { tier = $('Plan fallback searches').itemMatching(idx).json.tier || tier; } catch (e) {}
  if (r.error) { errors.push(`${tier}: ${r.error.message || JSON.stringify(r.error).slice(0, 200)}`); return; }
  if (r.linkedinUrl || r.publicIdentifier) people.push({ ...r, _tiers: [tier] });
});

return [{ json: { ...ctx, found: people, search_errors: errors, searches_run: (ctx.searches_run || 0) + reqs.length } }];

// Pass 1: dedupe across tiers, score on search data, keep the shortlist.
const ctx = $input.first().json;
const s = ctx.settings;

const normProfile = u => {
  const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i);
  return m ? `https://www.linkedin.com/in/${decodeURIComponent(m[1])}` : ''; // keep case: ACwAA... ids are case-sensitive
};
const locText = p => typeof p.location === 'string' ? p.location
  : (p.location && (p.location.linkedinText || p.location.text || (p.location.parsed && p.location.parsed.text))) || '';

const kw = [...(ctx.team_keywords || []), ...(ctx.peer_titles || [])].map(k => String(k).toLowerCase()).filter(Boolean);
const SENIOR = /\b(vp|vice president|director|head of|chief|cto|ceo|coo|cfo|founder|co-founder|owner|partner|president)\b/i;
const RECRUITER = /(recruit|talent acquisition|\bhr\b|human resources|sourcer)/i;
const contacted = new Set(ctx.contacted || []);

const byUrl = {};
for (const p of ctx.found || []) {
  const url = normProfile(p.linkedinUrl || (p.publicIdentifier ? `https://www.linkedin.com/in/${p.publicIdentifier}` : ''));
  if (!url) continue;
  if (!byUrl[url]) byUrl[url] = { p, url, tiers: new Set() };
  (p._tiers || []).forEach(t => byUrl[url].tiers.add(t));
}

let skippedContacted = 0;
const people = [];
for (const { p, url, tiers } of Object.values(byUrl)) {
  if (contacted.has(url)) { skippedContacted++; continue; }
  const cur = (p.currentPositions || [])[0] || {};
  const headline = p.headline || p.position || (cur.title ? `${cur.title}${cur.companyName ? ' at ' + cur.companyName : ''}` : '');
  if (RECRUITER.test(headline)) continue;
  // strip academic / honorific prefixes (ir., ing., dr., mr., prof., drs.) from names
  const TITLE = /^(ir|ing|dr|drs|mr|prof|msc|bsc)\.?\s+/i;
  const firstName = String(p.firstName || '').replace(TITLE, '').trim();
  const name = ([firstName, p.lastName].filter(Boolean).join(' ') || p.fullName || p.name || '').replace(TITLE, '').trim();
  const location = locText(p);
  let score = 0;
  const reasons = [];
  if (tiers.has('alumni')) { score += 4; reasons.push(`Alumnus/alumna of ${ctx.schools.join(' or ')} (search filter)`); }
  if (tiers.has('ex_colleague')) { score += 3; reasons.push('Worked at one of the candidate\'s past employers (search filter)'); }
  const hl = headline.toLowerCase();
  const hit = kw.find(k => hl.includes(k)) ||
    kw.map(k => k.split(/\s+/)).filter(w => w.length >= 2).map(w => w.slice(-2).join(' ')).find(k => hl.includes(k));
  if (hit) { score += 2; reasons.push(`Works on "${hit}" (headline)`); }
  if (ctx.city && location.toLowerCase().includes(ctx.city.toLowerCase())) score += 1;
  if (SENIOR.test(headline)) score -= 2;
  const tier = tiers.has('alumni') ? 'alumni' : tiers.has('ex_colleague') ? 'ex_colleague' : 'same_team';
  people.push({
    name, first_name: firstName || name.split(' ')[0] || '', last_name: p.lastName || '',
    headline, linkedin_url: url, profile_id: p.id || '', location, tier, tiers: [...tiers], score, match_reasons: reasons
  });
}
people.sort((a, b) => b.score - a.score);
const shortlist = people.slice(0, s.shortlist_size);

// Recruiters from the job postings (free, often empty)
const recruiters = [];
for (const j of ctx.jobs) {
  if (!j.recruiterName && !j.recruiterUrl) continue;
  recruiters.push({
    job_id: j.id, name: j.recruiterName || '', first_name: String(j.recruiterName || '').split(' ')[0],
    headline: 'Recruiter on the job posting', linkedin_url: normProfile(j.recruiterUrl), location: '',
    tier: 'recruiter', tiers: ['recruiter'], score: 0, match_reasons: ['Recruiter listed on the job posting']
  });
}

const { found, ...rest } = ctx;
return [{ json: {
  ...rest,
  shortlist,
  recruiters,
  stats: {
    searched: Object.keys(byUrl).length,
    alumni_found: people.filter(p => p.tiers.includes('alumni')).length,
    ex_colleagues_found: people.filter(p => p.tiers.includes('ex_colleague')).length,
    same_team_found: people.filter(p => p.tiers.includes('same_team')).length,
    skipped_already_contacted: skippedContacted
  }
} }];

// Attach full profiles (+ work emails at the company's own domain) to the shortlist.
const ctx = $('Score & shortlist').first().json;
const s = ctx.settings;

// Company email domain from the LinkedIn company page website
function registrable(host) {
  const parts = String(host || '').toLowerCase().replace(/^www\./, '').split('.').filter(Boolean);
  if (parts.length <= 2) return parts.join('.');
  const twoLevel = ['co.uk', 'com.au', 'co.jp', 'com.br', 'co.nz', 'co.za'];
  const last2 = parts.slice(-2).join('.');
  return twoLevel.includes(last2) ? parts.slice(-3).join('.') : last2;
}
let company_domain = '';
try {
  const co = $('Apify: company info').first().json || {};
  const site = String(co.website || co.websiteUrl || '');
  const host = (site.match(/^(?:https?:\/\/)?([^/?#:]+)/i) || [])[1] || '';
  company_domain = host ? registrable(host) : '';
} catch (e) { company_domain = ''; }
const normProfile = u => {
  const m = String(u || '').match(/linkedin\.com\/in\/([^/?#]+)/i);
  return m ? `https://www.linkedin.com/in/${decodeURIComponent(m[1])}` : ''; // keep case: ACwAA... ids are case-sensitive
};

const rows = $input.all().map(i => i.json).filter(r => r && Object.keys(r).length);
const errors = rows.filter(r => r.error).map(r => r.error.message || JSON.stringify(r.error).slice(0, 200));
const byUrl = {};
for (const r of rows) {
  if (r.error) continue;
  const keys = [r.linkedinUrl, r.url, r.publicIdentifier && `https://www.linkedin.com/in/${r.publicIdentifier}`,
    r.originalQuery && (r.originalQuery.url || r.originalQuery.query), r.id && `https://www.linkedin.com/in/${r.id}`]
    .map(normProfile).filter(Boolean);
  for (const k of keys) byUrl[k] = r;
  if (r.id) byUrl['id:' + r.id] = r;
}

// Emails can come as a string, an array of strings, or objects {email, status, ...}
function pickEmail(r) {
  const list = [];
  if (r.email) list.push(r.email);
  for (const e of (r.emails || [])) list.push(e);
  for (const e of list) {
    const addr = typeof e === 'string' ? e : (e && (e.email || e.address || e.value));
    if (!addr || !String(addr).includes('@')) continue;
    if (/@(gmail|googlemail|outlook|hotmail|yahoo|icloud|live|proton|protonmail|me)\./i.test(addr)) continue; // work emails only
    const dom = String(addr).split('@')[1].toLowerCase();
    if (company_domain && !(dom === company_domain || dom.endsWith('.' + company_domain))) continue; // email from another employer
    const status = String((e && (e.status || e.verificationStatus || e.quality)) || '').toLowerCase();
    if (/invalid|undeliverable/.test(status)) continue;
    return { email: addr, status: (!company_domain || /risky|catch|unknown|accept_all/.test(status)) ? 'guessed' : 'found' };
  }
  return null;
}

const shortlist = ctx.shortlist.map(c => {
  const full = byUrl[c.linkedin_url] || (c.profile_id && byUrl['id:' + c.profile_id]);
  if (!full) return { ...c, email: '', email_status: 'not_found' };
  const e = s.find_emails ? pickEmail(full) : null;
  return {
    ...c,
    headline: full.headline || c.headline,
    full: {
      education: full.education || full.educations || [],
      experience: full.experience || full.experiences || full.positions || []
    },
    email: e ? e.email : '',
    email_status: e ? e.status : 'not_found'
  };
});

const need_email = s.find_emails ? shortlist.filter(c => !c.email && c.name) : [];
return [{ json: { ...ctx, company_domain, shortlist, need_email, enrich_errors: errors } }];

// Email domain: the company website domain (from Collect enrichment); else a verified colleague email's domain.
const ctx = $input.first().json;
const FREE = /^(gmail|googlemail|outlook|hotmail|yahoo|icloud|live|proton|protonmail|me)\./i;
let domain = ctx.company_domain || '';
if (!domain) {
  const known = ctx.shortlist.filter(c => c.email_status === 'found').map(c => c.email).find(e => e && e.includes('@') && !FREE.test(e.split('@')[1]));
  if (known) domain = known.split('@')[1].toLowerCase();
}

if (!domain) return [{ json: { ...ctx, company_domain: '', run_finder: false } }];
return [{ json: {
  ...ctx,
  company_domain: domain,
  run_finder: true,
  finder_body: {
    people: ctx.need_email.map(c => `${c.name}, ${domain}`),
    discoverPattern: true,
    concurrency: 1,
    proxyConfiguration: { useApifyProxy: true }
  }
} }];

// Fill missing emails. Best source: the pattern of a verified colleague email at the same domain
// (e.g. jane.doe@ -> first.last). Fallback: the email finder. Both count as "guessed" (never auto-send),
// except finder results published on the company site ("found_on_site").
const ctx = $('Build finder input').first().json;
const domain = ctx.company_domain;
const rows = $input.all().map(i => i.json).filter(r => r && !r.error && r.mostLikelyEmail);

const clean = x => String(x || '').toLowerCase().replace(/ı/g, 'i').replace(/ø/g, 'o').replace(/ß/g, 'ss').replace(/æ/g, 'ae')
  .normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z\s-]/g, ' ').replace(/\s+/g, ' ').trim();
function nameParts(c) {
  const nameToks = String(c.name || '').split(/\s+/);
  const first = clean(c.first_name || nameToks[0]).split(' ')[0] || '';
  const lastToks = clean(c.last_name || nameToks.slice(1).join(' ')).split(/[\s-]+/).filter(Boolean);
  return { first, lastFull: lastToks.join(''), lastTok: lastToks[lastToks.length - 1] || '' };
}
const PATS = {
  'first.last': (f, l) => `${f}.${l}`, 'first-last': (f, l) => `${f}-${l}`, 'first_last': (f, l) => `${f}_${l}`,
  'firstlast': (f, l) => f + l, 'flast': (f, l) => f[0] + l, 'f.last': (f, l) => `${f[0]}.${l}`
};

// learn the pattern from verified colleague emails
let learned = null;
for (const c of ctx.shortlist) {
  if (!c.email || c.email_status !== 'found') continue;
  const [local, dom] = c.email.toLowerCase().split('@');
  if (dom !== domain) continue;
  const p = nameParts(c);
  for (const [pat, fn] of Object.entries(PATS)) {
    for (const lk of ['lastFull', 'lastTok']) {
      if (!learned && p.first && p[lk] && fn(p.first, p[lk]) === local) learned = { pat, lk };
    }
  }
}

const normName = x => clean(x).replace(/[^a-z]/g, '');
const rowName = r => r.fullName || r.name || [r.firstName, r.lastName].filter(Boolean).join(' ');
const used = new Set();

const shortlist = ctx.shortlist.map(c => {
  if (c.email) return c;
  const idx = rows.findIndex((r, i) => !used.has(i) && normName(rowName(r)) === normName(c.name));
  const r = idx >= 0 ? rows[idx] : null;
  if (idx >= 0) used.add(idx);
  if (r && r.method === 'found_on_site') {
    return { ...c, email: r.mostLikelyEmail, email_status: 'found', email_method: 'found_on_site' };
  }
  if (learned) {
    const p = nameParts(c);
    if (p.first && p[learned.lk]) {
      return { ...c, email: `${PATS[learned.pat](p.first, p[learned.lk])}@${domain}`, email_status: 'guessed', email_method: `colleague_pattern:${learned.pat}` };
    }
  }
  if (r) return { ...c, email: r.mostLikelyEmail, email_status: 'guessed', email_method: r.method || 'finder', email_confidence: Number(r.confidence || 0) };
  return c;
});

const { finder_body, ...rest } = ctx;
return [{ json: { ...rest, shortlist, email_pattern: learned ? learned.pat : null } }];

// Pass 2: confirm school / ex-employer from full profiles, add year bonus, build match_reasons from real data,
// keep the top N, then emit one item per job.
const ctx = $input.first().json;
const s = ctx.settings;
const cand = ctx.candidate || {};

const years = o => (JSON.stringify(o || {}).match(/\b(19[7-9]\d|20[0-3]\d)\b/g) || []).map(Number);
const candEnd = Math.max(0, ...(cand.education || []).map(e => Number(e && e.end_year) || 0)) || null;
const schoolTerms = (ctx.school_terms || []).filter(t => t.length > 2);
const pastKeys = (ctx.past_companies || []).map(p => ({
  name: p.name,
  keys: [String(p.name || '').toLowerCase(), ((p.url || '').match(/\/company\/([^/]+)/) || [])[1]].filter(k => k && k.length > 2)
}));

const scored = (ctx.shortlist || []).map(c => {
  let score = c.score;
  const reasons = c.match_reasons.filter(r => !/search filter/.test(r));
  if (c.full) {
    const edu = Array.isArray(c.full.education) ? c.full.education : [];
    const eduMatch = edu.find(e => { const t = JSON.stringify(e).toLowerCase(); return schoolTerms.some(k => t.includes(k)); });
    if (eduMatch) {
      const ys = years(eduMatch);
      const end = ys.length ? Math.max(...ys) : null;
      const deg = eduMatch.degree || eduMatch.degreeName || eduMatch.fieldOfStudy || eduMatch.subtitle || '';
      const schoolName = eduMatch.schoolName || eduMatch.school || ctx.schools.find(sch => JSON.stringify(eduMatch).toLowerCase().includes(String(sch).toLowerCase())) || ctx.schools[0];
      reasons.unshift(`${schoolName} alumnus/alumna${deg || end ? ` (${[deg, end].filter(Boolean).join(', ')})` : ''}`);
      if (!c.tiers.includes('alumni')) score += 4;
      if (end && candEnd && Math.abs(end - candEnd) <= 5) score += 1;
    } else if (c.tiers.includes('alumni')) {
      if (edu.length) score -= 4; // school not confirmed on the full profile
      else reasons.unshift(`Alumnus/alumna of ${ctx.schools.join(' or ')}`); // no education data returned: trust the search filter
    }
    const expText = JSON.stringify(c.full.experience || []).toLowerCase();
    const past = pastKeys.find(p => p.keys.some(k => expText.includes(k)));
    if (past) {
      reasons.push(`Also worked at ${past.name}`);
      if (!c.tiers.includes('ex_colleague')) score += 3;
    } else if (c.tiers.includes('ex_colleague')) {
      if ((c.full.experience || []).length) score -= 3;
      else reasons.push('Worked at one of the candidate\'s past employers');
    }
  } else {
    // not enriched: keep the search-filter facts, stated plainly
    if (c.tiers.includes('alumni')) reasons.unshift(`Alumnus/alumna of ${ctx.schools.join(' or ')}`);
    if (c.tiers.includes('ex_colleague')) reasons.push('Worked at one of the candidate\'s past employers');
  }
  const email_status = c.email_status || 'not_found';
  return {
    name: c.name, first_name: c.first_name, headline: c.headline, linkedin_url: c.linkedin_url, location: c.location,
    tier: c.tier, score, match_reasons: reasons,
    email: c.email || '', email_status,
    channel: c.email && email_status === 'found' ? 'email' : 'linkedin'
  };
}).filter(c => c.match_reasons.length > 0 || c.score > 0);

scored.sort((a, b) => b.score - a.score);
const top = scored.slice(0, s.contacts_per_job);

return ctx.jobs.map(job => {
  const recruiters = (ctx.recruiters || []).filter(r => r.job_id === job.id).map(r => ({
    name: r.name, first_name: r.first_name, headline: r.headline, linkedin_url: r.linkedin_url, location: '',
    tier: 'recruiter', score: 0, match_reasons: r.match_reasons, email: '', email_status: 'not_found', channel: 'linkedin'
  }));
  const contacts = [...top, ...recruiters];
  return { json: {
    job, candidate: cand, company: ctx.company, settings: s, contacts,
    summary: {
      ...(ctx.stats || {}),
      searches_run: ctx.searches_run || 0,
      emails_found: contacts.filter(c => c.email_status === 'found').length,
      team_keywords: ctx.team_keywords, peer_titles: ctx.peer_titles,
      errors: [...(ctx.search_errors || []), ...(ctx.enrich_errors || []), ...(ctx.keywords_error ? ['keywords: ' + ctx.keywords_error] : [])]
    }
  } };
});

// Parse + validate drafts, build the per-job output (contract §2). Runs once per job item.
const ctx = $('Rescore & expand').item.json;
const job = ctx.job, cand = ctx.candidate || {};
const res = $json || {};

let drafts = [];
let draft_error = null;
if (ctx.settings.draft_messages && ctx.contacts.length) {
  const text = Array.isArray(res.content) ? res.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (res.text || '');
  try { const m = text.match(/\{[\s\S]*\}/); drafts = (JSON.parse(m ? m[0] : text).drafts) || []; }
  catch (e) { draft_error = res.error ? JSON.stringify(res.error).slice(0, 300) : ('Drafts are not valid JSON: ' + text.slice(0, 200)); }
}

const slug = u => String(u || '').toLowerCase().replace(/^https?:\/\//, '').replace(/^[a-z]{2}\./, '').replace(/^www\./, '').replace(/\/+$/, '').split('?')[0];
const allowed = [job.url, cand.linkedin_url].filter(Boolean).map(slug);

const contacts = ctx.contacts.map((c, i) => {
  const d = drafts.find(x => Number(x.id) === i);
  if (!d) return { ...c, draft: null, draft_status: ctx.settings.draft_messages ? 'missing' : 'off' };
  const body = String(d.body || ''), note = String(d.linkedin_note || '');
  const issues = [];
  const wc = body.split(/\s+/).filter(Boolean).length;
  if (wc > 130) issues.push(`email ${wc} words`);
  if (note.length > 300) issues.push(`note ${note.length} chars`);
  const fn = String(c.first_name || c.name || '').split(/\s+/)[0];
  if (fn && !body.includes(fn) && !note.includes(fn)) issues.push('contact name missing');
  const links = (body + ' ' + note).match(/(https?:\/\/[^\s)>\]]+|(?:[a-z]{2}\.|www\.)?linkedin\.com\/[^\s)>\]]+)/gi) || [];
  const bad = links.filter(l => { const sl = slug(l).replace(/[.,;]+$/, ''); return !allowed.some(a => sl.startsWith(a) || a.startsWith(sl)); });
  if (bad.length) issues.push('unexpected links: ' + bad.join(' '));
  return {
    ...c,
    draft: { subject: String(d.subject || ''), body, linkedin_note: note },
    draft_status: issues.length ? 'needs_review' : 'draft',
    draft_issues: issues
  };
});

return { json: {
  auth_user_id: cand.auth_user_id || '',
  job_id: job.id,
  job_title: job.title,
  company: job.companyName,
  job_url: job.url,
  contacts,
  summary: { ...ctx.summary, ...(draft_error ? { draft_error } : {}) },
  // search failed (e.g. Apify concurrency limit) -> 'search_error' is not stored, so the job is retried on the next run
  status: !ctx.contacts.length ? (!((ctx.summary || {}).searched) && ((ctx.summary || {}).errors || []).length ? 'search_error' : 'no_contacts') : (draft_error ? 'draft_error' : (ctx.settings.draft_messages ? 'drafted' : 'contacts_only'))
} };

const rows = [];
const authUserId = $('Input').first().json.auth_user_id; // always set on every row
for (const it of $('Collect results').all()) {
  const r = it.json;
  for (const c of (r.contacts || [])) {
    if (!c.draft) continue;
    rows.push({ json: {
      auth_user_id: r.auth_user_id || authUserId,
      job_id: String(r.job_id || ''),
      job_title: r.job_title || '',
      company: r.company || '',
      job_url: r.job_url || '',
      contact_name: c.name || '',
      contact_linkedin_url: c.linkedin_url || '',
      contact_headline: c.headline || '',
      tier: c.tier || '',
      score: Number(c.score) || 0,
      match_reasons: (c.match_reasons || []).join('; '),
      email: c.email || '',
      email_status: c.email_status || '',
      channel: c.channel || '',
      subject: c.draft.subject,
      body: c.draft.body,
      linkedin_note: c.draft.linkedin_note,
      status: c.draft_status
    } });
  }
  // no contacts at all: store a marker row so this user-vacancy pair is not searched again
  if (!(r.contacts || []).length && r.status === 'no_contacts') {
    rows.push({ json: { auth_user_id: r.auth_user_id || authUserId, job_id: String(r.job_id || ''), job_title: r.job_title || '',
      company: r.company || '', job_url: r.job_url || '', contact_name: '', contact_linkedin_url: '', contact_headline: '',
      tier: '', score: 0, match_reasons: '', email: '', email_status: '', channel: '', subject: '', body: '', linkedin_note: '',
      status: 'no_contacts' } });
  }
}
return rows.length ? rows : [{ json: { __no_rows: true } }];

const j = $input.first().json || {};
const id = String(j.auth_user_id || '').trim();
if (!id) throw new Error('auth_user_id is required');
// worker_batch is only set when this workflow calls itself to process a group of companies in parallel
const batch = j.worker_batch && Array.isArray(j.worker_batch.companies) ? j.worker_batch : null;
return [{ json: { auth_user_id: id, worker_batch: batch } }];

// Real user: profile from `users`, recommended vacancies from `user_jobs` + `jobs`.
const MAX_JOBS = 0; // 0 = all recommended vacancies (sorted by priority_score). Each new company costs ~$0.15-0.45 of Apify credit.

const authUserId = $('Input').first().json.auth_user_id;
const user = $('Load user').first().json || {};
if (!user.auth_user_id) throw new Error(`No user with auth_user_id ${authUserId} in the users table`);

const parse = s => { try { const v = JSON.parse(s || '[]'); return Array.isArray(v) ? v : []; } catch (e) { return []; } };

const allUserJobs = $('Load user jobs').all().map(i => i.json).filter(r => r && r.job_id && !r.hidden);
const byKey = {};
for (const i of $('Load jobs').all()) { const j = i.json; if (j && j.job_id) byKey[j.job_id] = j; }

// user-vacancy pairs already in referral_drafts are kept as they are and not processed again
const done = new Set($input.all().map(i => i.json && i.json.job_id).filter(Boolean));

const userJobs = allUserJobs.filter(r => !done.has(r.job_id));
const jobs = userJobs
  .sort((a, b) => (b.priority_score || 0) - (a.priority_score || 0) || (b.match_score || 0) - (a.match_score || 0))
  .map(uj => {
    const j = byKey[uj.job_id];
    if (!j || j.is_active === false) return null;
    let raw = {};
    try { raw = JSON.parse(j.raw_data_json || '{}'); } catch (e) {}
    return {
      id: j.job_id,                               // jobs table key, e.g. linkedin:4470324179
      external_id: j.external_job_id || raw.id || '',
      title: j.title,
      companyName: j.company_name,
      companyUrl: j.company_url || raw.companyUrl || '',
      location: j.location || '',
      url: j.job_url || raw.url || '',
      description: j.description || raw.description || '',
      recruiterName: raw.recruiterName || '',
      recruiterUrl: raw.recruiterUrl || '',
      match_score: uj.match_score, priority_score: uj.priority_score
    };
  })
  .filter(Boolean)
  .slice(0, MAX_JOBS > 0 ? MAX_JOBS : undefined);

// Raw profile text for the Haiku parser (tables store CV fields as loose JSON string lists)
const profile_text = [
  `NAME (table): ${[user.first_name, user.last_name].filter(Boolean).join(' ')}`,
  `LOCATION: ${user.location || ''}, ${user.country || ''}`,
  `EDUCATION: ${parse(user.education_json).join(', ')}`,
  `EXPERIENCE: ${parse(user.experience_json).join(', ')}`,
  `PREVIOUS COMPANIES: ${parse(user.previous_companies_json).join('; ')}`,
  `CV:\n${String(user.cv_text || '').slice(0, 6000)}`
].join('\n');

return [{ json: { auth_user_id: user.auth_user_id, user, jobs, profile_text,
  recommended_jobs: allUserJobs.length, already_done: allUserJobs.length - userJobs.length } }];

// Past employers from the parsed CV -> LinkedIn company search (to get company URLs for the ex-colleague tier)
const res = $input.first().json || {};
const text = Array.isArray(res.content) ? res.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (res.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*\}/); p = JSON.parse(m ? m[0] : text); } catch (e) { p = {}; }
// Universities are covered by the alumni tier; a company search for them returns sub-schools (e.g. Amsterdam Business School)
const schools = (p.education || []).flatMap(e => [e && e.school, ...((e && e.school_aliases) || [])]).filter(Boolean).map(s => String(s).toLowerCase());
const isSchool = n => schools.includes(String(n).toLowerCase()) || /\b(university|universiteit|hogeschool|college|school of)\b/i.test(n);
const names = [...new Set((p.past_employers || []).map(e => e && e.name).filter(Boolean))].filter(n => !isSchool(n)).slice(0, 5);
return [{ json: { names, parse_ok: !!(p.education || p.past_employers), parse_error: (p.education || p.past_employers) ? null : text.slice(0, 300) } }];

// Structured candidate (from Haiku) + LinkedIn URLs of past employers -> one item per job for the referral pipeline.
const base = $('Build candidate & jobs').first().json;
const user = base.user;
const res = $('Parse candidate').first().json || {};

let text = Array.isArray(res.content) ? res.content.filter(c => c.type === 'text').map(c => c.text).join('\n') : (res.text || '');
let p = {};
try { const m = text.match(/\{[\s\S]*\}/); p = JSON.parse(m ? m[0] : text); } catch (e) { p = {}; }

// company search results (may be absent when no past employers)
let companies = [];
try { companies = $('Apify: resolve past companies').all().map(i => i.json).filter(r => r && !r.error && /linkedin\.com\/company\//.test(r.linkedinUrl || r.url || '')); } catch (e) {}
const norm = s => String(s || '').toLowerCase().replace(/\(.*?\)/g, '').replace(/[^a-z0-9]/g, '');
function findCompany(name) {
  const n = norm(name);
  if (!n) return null;
  return companies.find(c => norm(c.name) === n)
    || companies.find(c => norm(c.name).includes(n) || n.includes(norm(c.name)))
    || companies.find(c => c.originalQuery && norm(c.originalQuery.search || c.originalQuery.query) === n)
    || null;
}

const fullName = p.full_name || [user.first_name, user.last_name].filter(Boolean).join(' ');
const linkedin = user.linkedin_url || '';
const candidate = {
  auth_user_id: user.auth_user_id,
  name: fullName,
  linkedin_url: linkedin,
  headline: p.headline || user.profile_summary || '',
  location: user.location || '',
  education: (p.education || []).filter(e => e && e.school).map(e => ({
    school: e.school, school_aliases: e.school_aliases || [], degree: e.degree || '', end_year: Number(e.end_year) || null
  })),
  experience: (p.past_employers || []).filter(e => e && e.name).map(e => {
    const c = findCompany(e.name);
    return { company: e.name, title: e.title || '', company_linkedin_url: c ? (c.linkedinUrl || c.url) : '' };
  }),
  skills: (() => { try { return JSON.parse(user.skills_json || '[]'); } catch (e) { return []; } })().slice(0, 15),
  projects: (p.projects || []).slice(0, 4),
  email_signature: [fullName, user.email, linkedin].filter(Boolean).join(' · ')
};

if (!base.jobs.length) return [];
return base.jobs.map(job => ({ json: { job, candidate, auth_user_id: user.auth_user_id } }));

// Spread the companies over parallel worker runs of this same workflow.
// Each worker handles its companies one by one, so Apify runs at most WORKERS searches at a time.
// 2 workers: get_materials runs at the same time with 2 lanes, and Apify allows 5 concurrent runs.
const WORKERS = 2;
const companies = $input.all().map(i => i.json);
const n = Math.min(WORKERS, companies.length);
const buckets = Array.from({ length: n }, () => []);
// largest companies (most jobs) first, round-robin
companies.sort((a, b) => b.jobs.length - a.jobs.length).forEach((c, i) => buckets[i % n].push(c));
const id = $('Input').first().json.auth_user_id;
return buckets.map((b, k) => ({ json: {
  auth_user_id: id,
  worker: k + 1,
  worker_batch: { companies: b },
  companies: b.map(c => c.company.name),
  jobs: b.reduce((s, c) => s + c.jobs.length, 0)
} }));

const base = $('Build candidate & jobs').first().json;
const workers = $('Split into workers').all().map(i => ({ worker: i.json.worker, companies: i.json.companies, jobs: i.json.jobs }));
return [{ json: {
  auth_user_id: base.auth_user_id,
  status: 'started',
  recommended_jobs: base.recommended_jobs,
  already_done: base.already_done,
  new_jobs: base.jobs.length,
  workers,
  note: 'Workers run in parallel and write to the referral_drafts table (filter by auth_user_id).'
} }];
